CREATE TYPE "MembershipRole" AS ENUM ('STUDENT','PARENT','TEACHER','SCHOOL_ADMIN','CONTENT_EDITOR','ABA_OPERATOR');
CREATE TYPE "MembershipStatus" AS ENUM ('ACTIVE','SUSPENDED','REVOKED');
CREATE TYPE "VerificationStatus" AS ENUM ('PENDING','VERIFIED','REVOKED');
CREATE TABLE "user_profiles" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"auth_user_id" UUID NOT NULL,"display_name" TEXT NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "user_profiles_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "user_profiles_auth_user_id_key" ON "user_profiles"("auth_user_id");
CREATE TABLE "schools" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "schools_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "schools_organization_id_code_key" ON "schools"("organization_id","code"); CREATE INDEX "schools_organization_id_idx" ON "schools"("organization_id");
CREATE TABLE "classrooms" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"school_id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"academic_year" TEXT NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "classrooms_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "classrooms_school_id_code_academic_year_key" ON "classrooms"("school_id","code","academic_year"); CREATE INDEX "classrooms_school_id_academic_year_idx" ON "classrooms"("school_id","academic_year");
CREATE TABLE "memberships" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"user_profile_id" UUID NOT NULL,"organization_id" UUID NOT NULL,"school_id" UUID,"classroom_id" UUID,"role" "MembershipRole" NOT NULL,"status" "MembershipStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "memberships_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "memberships_user_profile_id_organization_id_role_school_id_classroom_id_key" ON "memberships"("user_profile_id","organization_id","role","school_id","classroom_id"); CREATE INDEX "memberships_user_profile_id_organization_id_idx" ON "memberships"("user_profile_id","organization_id"); CREATE INDEX "memberships_org_school_role_status_idx" ON "memberships"("organization_id","school_id","role","status");
CREATE TABLE "students" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"student_code" TEXT NOT NULL,"display_name" TEXT NOT NULL,"grade" INTEGER NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "students_pkey" PRIMARY KEY("id"),CONSTRAINT "students_grade_check" CHECK ("grade" BETWEEN 1 AND 12));
CREATE UNIQUE INDEX "students_organization_id_student_code_key" ON "students"("organization_id","student_code"); CREATE INDEX "students_organization_id_idx" ON "students"("organization_id");
CREATE TABLE "enrollments" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"student_id" UUID NOT NULL,"school_id" UUID NOT NULL,"classroom_id" UUID NOT NULL,"starts_at" DATE NOT NULL,"ends_at" DATE,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "enrollments_pkey" PRIMARY KEY("id"),CONSTRAINT "enrollments_dates_check" CHECK ("ends_at" IS NULL OR "ends_at" >= "starts_at"));
CREATE UNIQUE INDEX "enrollments_student_class_start_key" ON "enrollments"("student_id","classroom_id","starts_at"); CREATE INDEX "enrollments_student_ends_idx" ON "enrollments"("student_id","ends_at"); CREATE INDEX "enrollments_class_dates_idx" ON "enrollments"("classroom_id","starts_at","ends_at");
CREATE TABLE "guardian_links" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"guardian_user_id" UUID NOT NULL,"student_id" UUID NOT NULL,"verification_status" "VerificationStatus" NOT NULL DEFAULT 'PENDING',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "guardian_links_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "guardian_links_guardian_student_key" ON "guardian_links"("guardian_user_id","student_id"); CREATE INDEX "guardian_links_guardian_status_idx" ON "guardian_links"("guardian_user_id","verification_status");
CREATE TABLE "student_account_links" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"user_profile_id" UUID NOT NULL,"student_id" UUID NOT NULL,"status" "MembershipStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "student_account_links_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "student_account_links_user_student_key" ON "student_account_links"("user_profile_id","student_id"); CREATE INDEX "student_account_links_user_status_idx" ON "student_account_links"("user_profile_id","status");
